import { site, absoluteUrl } from '@/lib/site.config';
import { docs } from '@/lib/docs';

// Machine-readable site description for agents. Read-only by contract.

export function GET() {
  return Response.json({
    schema: 'starlight.site.v1',
    name: site.name,
    url: site.url,
    description: site.description,
    pages: [
      { path: '/', title: site.home.claim },
      { path: '/pricing', title: site.pricing.claim },
      ...docs.map((d) => ({ path: `/docs/${d.slug}`, title: d.title })),
    ],
    endpoints: {
      llms: absoluteUrl(site.agents.llms),
      mcp: { url: absoluteUrl(site.agents.mcp), transport: 'streamable-http', tools: ['get_pricing', 'list_docs'] },
    },
    authority: { read: true, write: false, payments: false, accounts: false },
    generator: 'starlight-glass-core-site-kit',
  });
}

import { site, formatPrice } from '@/lib/site.config';
import { docs } from '@/lib/docs';

// Stateless Model Context Protocol stub over Streamable HTTP, JSON responses only.
// Targets revision 2026-07-28 (stateless: server/discover, resultType, ttlMs,
// cacheScope) and still answers `initialize` for 2025-11-25 clients.
// Read-only: two tools over public site data. No sessions, no writes, no auth.
// Spec read 2026-11-21: research/craft/glass-core-docs-read-2026-11-21.md (section 4).

const CURRENT = '2026-07-28';
const SUPPORTED = [CURRENT, '2025-11-25', '2025-06-18', '2025-03-26'];
const TTL = { ttlMs: 300_000, cacheScope: 'public' as const };
const serverInfo = { name: `${site.name.toLowerCase()}-site`, version: '0.1.0' };
const instructions = 'Read-only public site data. No account, payment or write operations exist on this server.';

const tools = [
  {
    name: 'get_pricing',
    description: `Current public plans and prices for ${site.name}.`,
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: 'list_docs',
    description: `Documentation pages for ${site.name}, with URLs and summaries.`,
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
];

type Id = string | number | null | undefined;
type RpcRequest = { jsonrpc: '2.0'; id?: Id; method: string; params?: Record<string, unknown> };
type Reply = { status: number; body: unknown };

const ok = (id: Id, result: Record<string, unknown>): Reply => ({
  status: 200,
  body: { jsonrpc: '2.0', id: id ?? null, result: { resultType: 'complete', ...result, _meta: { 'io.modelcontextprotocol/serverInfo': serverInfo } } },
});
const fail = (id: Id, status: number, code: number, message: string): Reply => ({
  status,
  body: { jsonrpc: '2.0', id: id ?? null, error: { code, message } },
});
const text = (value: unknown) => ({ content: [{ type: 'text', text: JSON.stringify(value, null, 2) }], structuredContent: value, isError: false });

function handle(req: RpcRequest): Reply {
  switch (req.method) {
    case 'server/discover':
      return ok(req.id, { supportedVersions: SUPPORTED, capabilities: { tools: {} }, instructions, ...TTL });
    case 'initialize': // 2025-11-25 and earlier clients
      return {
        status: 200,
        body: { jsonrpc: '2.0', id: req.id ?? null, result: { protocolVersion: '2025-11-25', capabilities: { tools: { listChanged: false } }, serverInfo, instructions } },
      };
    case 'tools/list':
      return ok(req.id, { tools, ...TTL });
    case 'tools/call': {
      const name = req.params?.name;
      if (name === 'get_pricing')
        return ok(
          req.id,
          text({
            currency: site.currency,
            plans: site.pricing.plans.map((p) => ({ id: p.id, name: p.name, monthly: formatPrice(p.monthly), yearly: formatPrice(p.yearly), steps: p.steps })),
          }),
        );
      if (name === 'list_docs')
        return ok(req.id, text({ docs: docs.map((d) => ({ title: d.title, url: `${site.url}/docs/${d.slug}`, summary: d.summary })) }));
      return fail(req.id, 200, -32602, `Unknown tool: ${String(name)}`);
    }
    default:
      return fail(req.id, 404, -32601, `Method not found: ${req.method}`);
  }
}

export async function POST(request: Request) {
  const header = request.headers.get('mcp-protocol-version');
  if (header && !SUPPORTED.includes(header))
    return Response.json(fail(null, 400, -32022, `Unsupported protocol version: ${header}`).body, { status: 400 });
  let body: RpcRequest;
  try {
    body = await request.json();
  } catch {
    return Response.json(fail(null, 400, -32700, 'Parse error').body, { status: 400 });
  }
  if (!body || body.jsonrpc !== '2.0' || typeof body.method !== 'string')
    return Response.json(fail(null, 400, -32600, 'Invalid request').body, { status: 400 });
  const metaVersion = (body.params?._meta as Record<string, unknown> | undefined)?.['io.modelcontextprotocol/protocolVersion'];
  if (header && typeof metaVersion === 'string' && metaVersion !== header)
    return Response.json(fail(body.id, 400, -32020, 'MCP-Protocol-Version header does not match _meta').body, { status: 400 });
  if (body.id === undefined) return new Response(null, { status: 202 }); // notification
  const reply = handle(body);
  return Response.json(reply.body, { status: reply.status, headers: { 'MCP-Protocol-Version': header ?? CURRENT } });
}

// Stateless server: no GET stream, no session to delete.
const notAllowed = () => new Response('Method not allowed', { status: 405, headers: { Allow: 'POST' } });
export const GET = notAllowed;
export const DELETE = notAllowed;

import { ImageResponse } from 'next/og';
import { Mark } from '@/components/site/mark';

export const size = { width: 180, height: 180 };
export const contentType = 'image/png';

export default function AppleIcon() {
  return new ImageResponse(<Mark size={180} padding={0.18} />, size);
}

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { docs, getDoc } from '@/lib/docs';


export function generateStaticParams() {
  return docs.map((d) => ({ slug: d.slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const doc = getDoc(slug);
  return doc ? { title: doc.title, description: doc.summary, alternates: { canonical: `/docs/${doc.slug}` } } : {};
}

export default async function DocPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const doc = getDoc(slug);
  if (!doc) notFound();
  const index = docs.indexOf(doc);
  const prev = docs[index - 1];
  const next = docs[index + 1];
  const headings = doc.blocks.filter((b) => b.kind === 'h2');
  return (
    <article className="ks-article">
      <p className="ks-label">{doc.section}</p>
      <h1 className="ks-article__title">{doc.title}</h1>
      <p className="ks-lede">{doc.summary}</p>
      {headings.length > 1 ? (
        <nav aria-label="On this page" className="ks-toc">
          <span className="ks-label">On this page</span>
          {headings.map((h) => (
            <a key={h.id} href={`#${h.id}`}>
              {h.text}
            </a>
          ))}
        </nav>
      ) : null}
      {doc.blocks.map((b, i) => {
        if (b.kind === 'h2')
          return (
            <h2 key={i} id={b.id} className="ks-article__h2">
              {b.text}
            </h2>
          );
        if (b.kind === 'code')
          return (
            <pre key={i} className="ks-code" tabIndex={0} aria-label={`${b.lang} example`}>
              <code>{b.text}</code>
            </pre>
          );
        return <p key={i}>{b.text}</p>;
      })}
      <nav aria-label="Pagination" className="ks-pager">
        {prev ? (
          <Link href={`/docs/${prev.slug}`} rel="prev">
            <span className="ks-label">Previous</span>
            {prev.title}
          </Link>
        ) : (
          <span />
        )}
        {next ? (
          <Link href={`/docs/${next.slug}`} rel="next">
            <span className="ks-label">Next</span>
            {next.title}
          </Link>
        ) : null}
      </nav>
    </article>
  );
}

import type { ReactNode } from 'react';
import { DocsNav } from '@/components/site/docs-nav';
import { AgentSlot } from '@/components/site/agent-slot';

export default function DocsLayout({ children }: { children: ReactNode }) {
  return (
    <div className="ks-docs">
      <DocsNav />
      <div className="ks-docs__main">{children}</div>
      <aside className="ks-docs__aside">
        <AgentSlot title="Ask about these docs" />
      </aside>
    </div>
  );
}

import { redirect } from 'next/navigation';

export default function DocsIndex() {
  redirect('/docs/introduction');
}

import { ImageResponse } from 'next/og';
import { Mark } from '@/components/site/mark';

export const size = { width: 32, height: 32 };
export const contentType = 'image/png';

export default function Icon() {
  return new ImageResponse(<Mark size={32} />, size);
}

import type { Metadata, Viewport } from 'next';
import type { ReactNode } from 'react';
import '@fontsource/instrument-sans/400.css';
import '@fontsource/instrument-sans/600.css';
import '@fontsource/instrument-serif/400.css';
import '@fontsource/instrument-serif/400-italic.css';
import '@fontsource/ibm-plex-mono/400.css';
import '@/components/ui/starlight/tokens.css';
import '@/components/ui/starlight/components.css';
import './site.css';
import { site } from '@/lib/site.config';
import { SiteHeader } from '@/components/site/site-header';
import { SiteFooter } from '@/components/site/site-footer';

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: { default: `${site.name}: ${site.tagline}`, template: `%s · ${site.name}` },
  description: site.description,
  applicationName: site.name,
  openGraph: { title: site.name, description: site.description, url: site.url, siteName: site.name, type: 'website' },
  alternates: { types: { 'text/plain': site.agents.llms } },
};

// Phone contract: cover the notch area, allow pinch zoom to 5x, never disable scaling.
export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  maximumScale: 5,
  viewportFit: 'cover',
  themeColor: site.themeColor,
  colorScheme: 'dark',
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang={site.locale} data-theme="midnight" suppressHydrationWarning>
      <head>
        {/* Marks JS as available before first paint so motion start states never flash. */}
        <script dangerouslySetInnerHTML={{ __html: "document.documentElement.dataset.js='1'" }} />
      </head>
      <body className="ks-body">
        <a className="ks-skip" href="#main">
          Skip to content
        </a>
        <SiteHeader />
        <main id="main" tabIndex={-1}>
          {children}
        </main>
        <SiteFooter />
      </body>
    </html>
  );
}

import { site, absoluteUrl, formatPrice } from '@/lib/site.config';
import { docs } from '@/lib/docs';

// llms.txt (llmstxt.org): H1, blockquote summary, then H2 sections of links.

export function GET() {
  const lines = [
    `# ${site.name}`,
    '',
    `> ${site.description}`,
    '',
    'This site is read-only for agents. No endpoint here can create accounts, take payments or change data.',
    '',
    '## Docs',
    '',
    ...docs.map((d) => `- [${d.title}](${absoluteUrl(`/docs/${d.slug}`)}): ${d.summary}`),
    '',
    '## Pricing',
    '',
    ...site.pricing.plans.map(
      (p) => `- [${p.name}](${absoluteUrl(`/pricing#${p.id}`)}): ${formatPrice(p.monthly)} per month, ${p.steps}. ${p.summary}`,
    ),
    '',
    '## Optional',
    '',
    `- [Site manifest](${absoluteUrl(site.agents.wellKnown)}): pages, endpoints and authority as JSON`,
    `- [MCP endpoint](${absoluteUrl('/docs/agents')}): stateless Streamable HTTP, read-only tools`,
    '',
  ];
  return new Response(lines.join('\n'), { headers: { 'content-type': 'text/plain; charset=utf-8' } });
}

import type { MetadataRoute } from 'next';
import { site } from '@/lib/site.config';

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: site.name,
    short_name: site.name,
    description: site.description,
    start_url: '/',
    display: 'standalone',
    background_color: site.themeColor,
    theme_color: site.themeColor,
    icons: [
      { src: '/pwa-icon/192', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/pwa-icon/512', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/pwa-icon/maskable', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}

import Link from 'next/link';
import { site } from '@/lib/site.config';
import { ShaderField } from '@/components/site/shader-field';
import { RunLedger } from '@/components/site/run-ledger';

export default function Home() {
  const { home } = site;
  return (
    <>
      <section className="ks-open" aria-labelledby="claim">
        <ShaderField />
        <div className="ks-open__inner">
          <h1 id="claim" className="ks-claim">
            {home.claim}
          </h1>
          <p className="ks-lede">{home.lede}</p>
          <Link className="sl-button sl-button--primary ks-action" href={site.primaryAction.href}>
            {site.primaryAction.label}
          </Link>
        </div>
      </section>

      <section className="ks-screen ks-evidence" aria-labelledby="ledger-claim">
        <div className="ks-evidence__text">
          <h2 id="ledger-claim" className="ks-heading">
            {home.ledger.claim}
          </h2>
          <Link className="ks-link" href={home.ledger.action.href}>
            {home.ledger.action.label}
          </Link>
        </div>
        <RunLedger label={home.ledger.label} steps={home.ledger.steps} verdict={home.ledger.verdict} />
      </section>

      <section className="ks-screen" aria-labelledby="method">
        <h2 id="method" className="ks-heading">
          {home.method.title}
        </h2>
        <ol className="ks-method">
          {home.method.steps.map((step) => (
            <li key={step}>{step}</li>
          ))}
        </ol>
        <Link className="ks-link" href={home.method.action.href}>
          {home.method.action.label}
        </Link>
      </section>

      <section className="ks-screen ks-close" aria-labelledby="price">
        <h2 id="price" className="ks-heading ks-heading--large">
          {home.price.claim}
        </h2>
        <Link className="sl-button sl-button--secondary ks-action" href={home.price.action.href}>
          {home.price.action.label}
        </Link>
      </section>
    </>
  );
}

import type { Metadata } from 'next';
import { site, absoluteUrl } from '@/lib/site.config';
import { PricingPlans } from '@/components/site/pricing-plans';
import { JsonLd } from '@/components/site/json-ld';

export const metadata: Metadata = {
  title: 'Pricing',
  description: site.pricing.lede,
  alternates: { canonical: '/pricing' },
};

function productJsonLd() {
  return {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: site.name,
    description: site.description,
    brand: { '@type': 'Brand', name: site.name },
    url: absoluteUrl('/pricing'),
    image: absoluteUrl('/pwa-icon/512'),
    offers: site.pricing.plans
      .filter((plan) => plan.monthly !== null)
      .map((plan) => ({
        '@type': 'Offer',
        name: `${site.name} ${plan.name}`,
        price: String(plan.monthly),
        priceCurrency: site.currency,
        url: absoluteUrl(`/pricing#${plan.id}`),
        availability: 'https://schema.org/InStock',
        description: `${plan.steps}. ${plan.summary}`,
      })),
  };
}

export default function Pricing() {
  const { pricing } = site;
  return (
    <div className="ks-page">
      <JsonLd data={productJsonLd()} />
      <header className="ks-page__head">
        <h1 className="ks-claim ks-claim--page">{pricing.claim}</h1>
        <p className="ks-lede">{pricing.lede}</p>
      </header>
      <PricingPlans plans={pricing.plans} />
      <section className="ks-faq" aria-labelledby="faq">
        <h2 id="faq" className="ks-heading">
          Questions before you start
        </h2>
        {pricing.faq.map((item) => (
          <details key={item.q} className="ks-faq__item">
            <summary>{item.q}</summary>
            <p>{item.a}</p>
          </details>
        ))}
      </section>
    </div>
  );
}

import { ImageResponse } from 'next/og';
import { Mark } from '@/components/site/mark';

// Real PNG icons for the web app manifest, generated at build time.

const variants = {
  '192': { px: 192, padding: 0.12 },
  '512': { px: 512, padding: 0.12 },
  // Maskable icons keep the mark inside the central 80% safe zone.
  maskable: { px: 512, padding: 0.26 },
} as const;

export function generateStaticParams() {
  return Object.keys(variants).map((size) => ({ size }));
}

export async function GET(_req: Request, { params }: { params: Promise<{ size: string }> }) {
  const { size } = await params;
  const v = variants[size as keyof typeof variants];
  if (!v) return new Response('Not found', { status: 404 });
  return new ImageResponse(<Mark size={v.px} padding={v.padding} />, { width: v.px, height: v.px });
}

/* Glass Core site kit. Reads Glass Core tokens (--sl-*); adds layout and type.
   Phone first. Hover only inside (hover: hover) and (pointer: fine).
   No bare viewport-height units: svh for screens, dvh where chrome matters. */

:root {
  --ks-gutter: max(20px, env(safe-area-inset-left), env(safe-area-inset-right));
  --ks-max: 1180px;
  --ks-read: 68ch;
  --ks-claim: clamp(2.6rem, 10.5vw, 6rem);
  --ks-heading: clamp(2rem, 7.4vw, 3.6rem);
  --ks-body: 1.0625rem;
  --ks-row: 64px;
  --ks-lens-bleed: 14px;
  --ks-lens-scale: 1.04;
}
@media (min-width: 960px) {
  :root { --ks-row: 54px; --ks-lens-bleed: 22px; --ks-lens-scale: 1.03; }
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; scroll-padding-top: 5rem; }
body.ks-body {
  margin: 0;
  background: var(--sl-bg);
  color: var(--sl-text);
  font-family: var(--sl-font-sans);
  font-size: var(--ks-body);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
main { display: block; outline: none; }
a { color: inherit; }
p { margin: 0; }
h1, h2, h3 { margin: 0; font-weight: 400; }

:where(a, summary, input, button):focus-visible { outline: 2px solid var(--sl-accent); outline-offset: 3px; border-radius: 4px; }

.ks-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ks-skip { position: absolute; left: var(--ks-gutter); top: -100px; z-index: 10; padding: 10px 14px; background: var(--sl-accent); color: var(--sl-accent-ink); border-radius: 8px; text-decoration: none; }
.ks-skip:focus { top: max(12px, env(safe-area-inset-top)); }

.ks-label { font-family: var(--sl-font-mono); font-size: 0.78rem; letter-spacing: 0.02em; color: var(--sl-muted); font-weight: 400; }

/* Header and footer */
.ks-header {
  position: absolute; inset: 0 0 auto 0; z-index: 3;
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: max(14px, env(safe-area-inset-top)) var(--ks-gutter) 14px;
  max-width: calc(var(--ks-max) + 2 * var(--ks-gutter)); margin-inline: auto;
}
.ks-wordmark { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; font-weight: 600; font-size: 1rem; letter-spacing: 0.01em; text-decoration: none; }
.ks-wordmark svg { color: var(--sl-accent); }
.ks-nav { display: flex; gap: 4px; }
.ks-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; text-decoration: none; color: var(--sl-muted); font-size: 0.95rem; }
.ks-nav a:last-child { padding-right: 0; }

.ks-footer {
  display: grid; gap: 20px;
  max-width: calc(var(--ks-max) + 2 * var(--ks-gutter)); margin-inline: auto;
  padding: 56px var(--ks-gutter) max(40px, env(safe-area-inset-bottom));
  border-top: 1px solid color-mix(in srgb, var(--sl-line) 45%, transparent);
  color: var(--sl-muted); font-size: 0.95rem;
}
.ks-footer__agents { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 18px; }
.ks-footer__agents a { display: inline-flex; align-items: center; min-height: 44px; font-family: var(--sl-font-mono); font-size: 0.85rem; color: var(--sl-text); text-underline-offset: 4px; text-decoration-color: color-mix(in srgb, var(--sl-text) 35%, transparent); }
.ks-footer__note { font-size: 0.85rem; }
@media (min-width: 960px) {
  .ks-footer { grid-template-columns: 1fr auto; align-items: center; }
  .ks-footer__note { grid-column: 1 / -1; }
}

/* Type */
.ks-claim { font-family: var(--sl-font-serif); font-size: var(--ks-claim); line-height: 1.02; letter-spacing: -0.012em; max-width: 13ch; text-wrap: balance; }
.ks-claim--page { font-size: clamp(2.4rem, 9vw, 4.6rem); max-width: 16ch; }
.ks-heading { font-family: var(--sl-font-serif); font-size: var(--ks-heading); line-height: 1.06; letter-spacing: -0.008em; max-width: 16ch; text-wrap: balance; }
.ks-heading--large { font-size: clamp(2.3rem, 9vw, 4.8rem); max-width: 14ch; }
.ks-lede { color: var(--sl-muted); font-size: clamp(1.0625rem, 2.6vw, 1.25rem); line-height: 1.5; max-width: 36ch; text-wrap: pretty; }
.ks-link { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; color: var(--sl-accent); text-decoration: underline; text-underline-offset: 5px; text-decoration-thickness: 1px; font-weight: 600; font-size: 1rem; }
.ks-link::after { content: '→'; text-decoration: none; display: inline-block; }
.ks-action { font-size: 0.95rem; min-height: 48px; padding-inline: 22px; text-decoration: none; }

/* Screen 1: the opening field */
.ks-open { position: relative; isolation: isolate; min-height: 100svh; display: flex; align-items: flex-end; overflow: hidden; }
.ks-open__inner {
  position: relative; z-index: 1; width: 100%;
  max-width: calc(var(--ks-max) + 2 * var(--ks-gutter)); margin-inline: auto;
  display: grid; gap: 22px; justify-items: start;
  padding: 7rem var(--ks-gutter) max(15svh, 5rem);
}
.ks-open__inner .ks-action { margin-top: 10px; }
.ks-field { position: absolute; inset: 0; z-index: -1; background:
  radial-gradient(120% 70% at 78% 18%, rgb(155 216 205 / 0.30), transparent 60%),
  radial-gradient(90% 60% at 12% 42%, #1d3a3f, transparent 70%),
  var(--sl-bg); }
.ks-field::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to bottom, rgb(16 24 32 / 0) 30%, rgb(16 24 32 / 0.55) 70%, var(--sl-bg)); }
.ks-field__canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; transition: opacity 700ms var(--sl-ease); }
