/* Screens */
.ks-screen {
  max-width: calc(var(--ks-max) + 2 * var(--ks-gutter)); margin-inline: auto;
  min-height: 100svh; display: flex; flex-direction: column; justify-content: center; gap: 28px;
  padding: clamp(5rem, 16svh, 10rem) var(--ks-gutter);
}
.ks-evidence__text { display: grid; gap: 18px; justify-items: start; }
@media (min-width: 960px) {
  /* Desktop composes screens by rhythm, not by viewport height. */
  .ks-screen { min-height: 0; padding-block: clamp(7rem, 18svh, 12rem); }
}
@media (min-width: 960px) {
  .ks-evidence { display: grid; grid-template-columns: 5fr 7fr; align-items: center; gap: 7vw; }
