.ks-ledger__rows { list-style: none; margin: 0; padding: 0; }
.ks-step {
  height: var(--ks-row); display: grid; align-content: center; column-gap: 12px; row-gap: 2px;
  grid-template-columns: 2.1em minmax(0, 1fr) auto;
  grid-template-areas: 'n tool status' '. detail detail';
  border-top: 1px solid color-mix(in srgb, var(--sl-line) 28%, transparent);
  font-family: var(--sl-font-mono); font-size: 0.875rem;
}
.ks-step:first-child { border-top: 0; }
.ks-step__n { grid-area: n; color: var(--sl-muted); }
.ks-step__tool { grid-area: tool; color: var(--sl-text); }
.ks-step__detail { grid-area: detail; color: var(--sl-muted); font-size: 0.8rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
