.ks-step__queued { display: none; color: var(--sl-muted); }
.ks-step__verified { color: var(--sl-success); }
.ks-step[data-flagged] .ks-step__verified { color: var(--sl-danger); }
.ks-step[data-flagged] .ks-step__verified::before { content: '◆ '; }
.ks-step[data-state='queued'] .ks-step__queued { display: inline; }
.ks-step[data-state='queued'] .ks-step__verified { display: none; }
.ks-step[data-state='queued'] .ks-step__tool { color: var(--sl-muted); }
.ks-ledger__verdict { color: var(--sl-text); max-width: 44ch; }

/* Lens: magnifies a copy of the rows beneath it. It refracts real content and
   carries no information of its own (aria-hidden). */
.ks-ledger { --lens-i: var(--lens-final, 0); }
.ks-lens {
  position: absolute; left: calc(var(--ks-lens-bleed) * -1); right: calc(var(--ks-lens-bleed) * -1); top: 0; height: var(--ks-row);
  transform: translateY(calc(var(--ks-row) * var(--lens-i)));
  border-radius: 14px; overflow: hidden; pointer-events: none;
  background: color-mix(in srgb, var(--sl-bg) 88%, var(--sl-accent));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.22), inset 0 -1px 0 rgb(0 0 0 / 0.35), 0 0 0 1px rgb(155 216 205 / 0.35), 0 14px 32px rgb(0 0 0 / 0.35);
}
.ks-lens::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(180deg, rgb(255 255 255 / 0.10), transparent 38%, transparent 70%, rgb(155 216 205 / 0.10)); }
.ks-lens__content { position: absolute; left: var(--ks-lens-bleed); right: var(--ks-lens-bleed); top: 0; transform: translateY(calc(var(--ks-row) * var(--lens-i) * -1)); }
.ks-lens__content .ks-ledger__rows { transform: scale(var(--ks-lens-scale)); transform-origin: 50% calc(var(--ks-row) * (var(--lens-i) + 0.5)); }

