//       <YourChatSurface />
//     </StarlightCopilotProvider>
//   </AgentSlot>

export type AgentSlotProps = {
  title: string;
  children?: ReactNode;
};

export function AgentSlot({ title, children }: AgentSlotProps) {
  return (
